// Function to check if the sequence of numbers in a vector is monotonic.
// It takes a vector of integers and two other parameters: 'k' and 'strict'.
bool monotonic(std::vector<int> l, int k, bool strict = false) {
    int size = l.size();

    // If 'strict' is set to true, checks whether the difference between each pair of numbers is equal to 'k'.
    if(strict) {
        for (int i = 0; i < size - 1; i++) {
            if (l[i+1] - l[i] != k) {
                return false;
            }
        }
    } 
    // If 'strict' is set to false, it also allows for the difference to be zero.
    else {
        for (int i = 0; i < size - 1; i++) {
            if ((l[i+1] - l[i] != k) && (l[i+1] - l[i] != 0)) {
                return false;
            }
        }
    }
    return true;
}

