```JavaScript
function arrayManipulation(arr) {
  // Filtering only the number type values in the array
  const filteredArr = arr.filter(e => typeof e === 'number');

  // Sorting the filtered array in ascending order
  const sortedArr = filteredArr.sort((a, b) => a - b);

  // Calculating the mean
  const mean = sortedArr.reduce((a, b) => a + b, 0) / sortedArr.length;

  // Calculating the median
  let median;
  if (sortedArr.length % 2 === 0) {
    median = (sortedArr[sortedArr.length / 2 - 1] + sortedArr[sortedArr.length / 2]) / 2;
  } else {
    median = sortedArr[Math.floor(sortedArr.length / 2)];
  }

  // Calculating the mode
  const counts = sortedArr.reduce((acc, val) => {
    if (acc.hasOwnProperty(val)) {
      acc[val] += 1;
    } else {
      acc[val] = 1;
    }
    return acc;
  }, {});

  let maxCount = 0;
  let mode = [];
  for(const [num, count] of Object.entries(counts)) {
    if(count === maxCount){
      mode.push(Number(num));
    } else if(count > maxCount){
      mode = [Number(num)];
      maxCount = count;
    }
  }

  return {
    sorted: sortedArr,
    mean: mean, 
    median: median, 
    mode: mode
  };
}
