function findPeaks(arr) {
    let peaks = [];
    if(arr.length > 0){
        // Check peak point at the start of the array
        if(arr[0] > arr[1]){
            peaks.push(arr[0]);
        }

        // Check peak points in the middle of array
        for (let i = 1; i < arr.length - 1; i++) {
            if (arr[i] > arr[i - 1] && arr[i] > arr[i + 1]) {
                peaks.push(arr[i]);
            }
