using namespace std;

double median(vector<double> scores, int length)
{
    sort(scores.begin(), scores.end());
    if (length % 2 != 0)
        return (double)scores[length / 2];

    return (double)(scores[(length - 1) / 2] + scores[length / 2]) / 2.0;
}

int main() 
{
    vector<double> scores = {1.5, 3.0, 4.5, 2.5, 5.0};
    int length = scores.size();
    cout << "Median: " << median(scores, length) << endl;
    return 0;
}
