    max_value = float('-inf')
    for item in lst:
        if isinstance(item, list):
            if not is_excluded(item):
                nested_max = find_max_in_nested(item)
                max_value = max(max_value, nested_max)
        elif isinstance(item, (int, float)):
            max_value = max(max_value, item)
