```javascript
function wordStrings(s) {
    // Splitting the string by the commas and spaces
    let splitWords = s.split(/[, ]/);

    // Initializing an empty list of Strings
    let words = [];

    for (let i=0; i<splitWords.length; i++) {
        let word = splitWords[i];
        // Checking if the word contains only asterisks
        if (/^\*+$/.test(word)) {
            // If so, add "hidden" to the list
            words.push("hidden");
        } else {
            // Otherwise, add the word itself
            words.push(word);
        }
    }

