import math

def _is_perfect_square(x: int) -> bool:
    """Return True if x is a perfect square."""
    if x < 0:
        return False
    root = math.isqrt(x)
    return root * root == x


def _is_fibonacci(num: int) -> bool:
    """
    A number N is Fibonacci iff 5*N^2 + 4 or 5*N^2 - 4 is a perfect square.
    """
    return _is_perfect_square(5 * num * num + 4) or _is_perfect_square(5 * num * num - 4)


def _is_prime(num: int) -> bool:
    """Simple deterministic primality test for 32-bit integers."""
    if num <= 1:
        return False
    if num <= 3:  # 2 and 3 are prime
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True


def is_prime_and_fibonacci(n: int) -> bool:
    """
    Return True if n is both a prime number and a Fibonacci number, otherwise False.
    """
    return _is_prime(n) and _is_fibonacci(n)

