Here is a Python solution that uses two heaps, a max heap for the lower half of the number stream, and a min heap for the upper half. 

This way, we can efficiently add numbers, find the median, and remove the numbers from the data stream. The heaps are implemented using Python's `heapq` module. The median is always at the top of one of the heaps.

```python
import heapq

class MedianFinder:

    def __init__(self):
        """
        initialize your data structure here.
        """
        self.max_heap = []
        self.min_heap = []

    def addNum(self, num: int) -> None:
        if len(self.min_heap) == len(self.max_heap):
            max_low = -heapq.heappushpop(self.max_heap, -num)
            heapq.heappush(self.min_heap, max_low)
        else:
            min_high = heapq.heappushpop(self.min_heap, num)
            heapq.heappush(self.max_heap, -min_high)

    def findMedian(self) -> float:
        if len(self.min_heap) == len(self.max_heap):
            return (self.min_heap[0] - self.max_heap[0]) / 2.0
        else:
            return float(self.min_heap[0])

    def removeNum(self, num: int) -> None:
        try:
            self.max_heap.remove(-num)
            heapq.heapify(self.max_heap)
        except ValueError:
            try:
                self.min_heap.remove(num)
                heapq.heapify(self.min_heap)
            except ValueError:
                pass
