import sys
import json
from collections import OrderedDict

def process_obj(obj, seen, placeholders):
    if isinstance(obj, dict):
        obj_id = id(obj)
        if obj_id in seen:
            if obj_id not in placeholders:
                placeholders[obj_id] = f"_circular_ref_{len(placeholders)}"
            return placeholders[obj_id]
        seen.add(obj_id)
        new_dict = OrderedDict()
        for key in sorted(obj.keys()):
            value = obj[key]
            if value is not None:
                processed_v = process_obj(value, seen, placeholders)
                # If value is None (by recursion), skip
                if processed_v is not None:
                    new_dict[key] = processed_v
        seen.remove(obj_id)
        return new_dict
    elif isinstance(obj, list):
        new_list = []
        for item in obj:
            if item is not None:
                processed_i = process_obj(item, seen, placeholders)
                if processed_i is not None:
                    new_list.append(processed_i)
        return new_list
    else:
        return obj

def main():
    s = sys.stdin.read()
    if not s.strip():
        obj = {}
    else:
        obj = json.loads(s)
    placeholders = {}
    seen = set()
    safe_obj = process_obj(obj, seen, placeholders)
    json_str = json.dumps(safe_obj, indent=4)
    print(json_str)

