import string

def backtrack(current_word: str, path: list[str], end_word: str, word_set: set[str]) -> list[str]:
    if current_word == end_word:
        return path

    for i in range(len(current_word)):
        for c in string.ascii_lowercase:
            transformed_word = current_word[:i] + c + current_word[i + 1:]
            if transformed_word in word_set:
                word_set.remove(transformed_word)
                result = backtrack(transformed_word, [*path, transformed_word], end_word, word_set)
                if result:
                    return result
                word_set.add(transformed_word)

    return []


def word_ladder(begin_word: str, end_word: str, word_set: set[str]) -> list[str]:
    if end_word not in word_set:
        return []

    return backtrack(begin_word, [begin_word], end_word, word_set)

import sys
import math
class Shape:
    def area(self):
        raise NotImplementedError()
    def perimeter(self):
        raise NotImplementedError()
class Rectangle(Shape):
    def __init__(self, width, height):
        if not isinstance(width, (int, float)) or not isinstance(height, (int, float)):
            raise ValueError
        if width <= 0 or height <= 0:
            raise ValueError
        self.width = width
        self.height = height
    def area(self):
        return self.width * self.height
    def perimeter(self):
        return 2 * (self.width + self.height)
class Circle(Shape):
    def __init__(self, radius):
        if not isinstance(radius, (int, float)):
            raise ValueError
        if radius <= 0:
            raise ValueError
        self.radius = radius
    def area(self):
        return math.pi * self.radius ** 2
    def perimeter(self):
        return 2 * math.pi * self.radius
class Triangle(Shape):
    def __init__(self, side1, side2, side3):
        if not all(isinstance(side, (int, float)) for side in (side1, side2, side3)):
            raise ValueError
        if any(side <= 0 for side in (side1, side2, side3)):
            raise ValueError
        if side1 + side2 <= side3 or side1 + side3 <= side2 or side2 + side3 <= side1:
            raise ValueError
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3
    def area(self):
        s = (self.side1 + self.side2 + self.side3) / 2
        area = math.sqrt(s * (s - self.side1) * (s - self.side2) * (s - self.side3))
        return area
    def perimeter(self):
        return self.side1 + self.side2 + self.side3

