```java
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class SetOperator {
    private Set<Integer> set;

    public SetOperator(int[] data) {
        Set<Integer> tempSet = new HashSet<>();
        for (int value : data) {
            if (!tempSet.add(value)) {
                throw new IllegalArgumentException("Error: Duplicate values are not allowed.");
            }
        }
        set = tempSet;
    }

    public boolean isSubset(int[] subset) {
        Set<Integer> subsetSet = new HashSet<>();
        for (int value : subset) subsetSet.add(value);

        return set.containsAll(subsetSet);
    }

    public int[] minMax() {
        if (set.isEmpty()) return new int[]{};

        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        for (int value : set) {
            if (value < min) min = value;
            if (value > max) max = value;
        }
        return new int[]{min, max};
    }

    public boolean contains(int value) {
        return set.contains(value);
    }

    public static void main(String[] args) {
        try {
            SetOperator sop = new SetOperator(new int[] {2, 3, 5, 4, 2, 3});
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }

        SetOperator sop1 = new SetOperator(new int[] {2, 3, 5, 4});
        System.out.println(Arrays.toString(sop1.minMax())); // [2, 5]
        System.out.println(sop1.isSubset(new int[] {3, 5, 2})) ; // true
        System.out.println(sop1.contains(3)); // true
        System.out.println(sop1.contains(10)); // false
    }
}
