    let sum = 0;
    let isSecondDigit = false;
    for (let i = cardNumber.length - 1; i >= 0; i--) {
        let digit = parseInt(cardNumber[i]);

        if (isSecondDigit){
            digit *= 2;
            if(digit > 9){
                digit -= 9;
            }
        }
