def longest_increasing_subsequence(nums):
    if not nums:
        return []
    dp = [1] * len(nums)
    prev_index = [-1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev_index[i] = j
    max_len = max(dp)
    max_length_index = dp.index(max_len)
    lis = []
    while max_length_index != -1:
        lis.append(nums[max_length_index])
        max_length_index = prev_index[max_length_index]
    lis.reverse()
    return lis

