from collections.abc import Iterable
from typing import Iterator, Callable, Union, Any


def filter_parameters(
    parameters: Iterable,
    selector: Union[str, Iterable[str], Callable[[Any], bool]]
) -> Iterator:
    """
    Yield parameters whose 'name' matches the selector rule.

    parameters : any iterable whose items expose a name through either
                 - a mapping interface with key 'name'  (e.g. {'name': 'w'})
                 - an attribute called 'name'            (e.g. obj.name)
    selector   : - str                     -> exact name match
                 - iterable of str         -> name contained in the iterable
                 - callable(param) -> bool -> the callable decides
                 any other kind of selector results in an empty iterator
    """

    # helper to obtain a parameter's name independent of representation
    def _get_name(param, default=None):
        try:                     # mapping first
            return param['name']
        except (TypeError, KeyError):
            return getattr(param, 'name', default)

    # 1. selector is a function
    if callable(selector):
        return (p for p in parameters if selector(p))

    # 2. selector is a single string
    if isinstance(selector, str):
        return (p for p in parameters if _get_name(p) == selector)

    # 3. selector is an iterable of strings (but *not* a string itself)
    if isinstance(selector, Iterable) and not isinstance(selector, (str, bytes)):
        selector_set = set(selector)     # membership lookup is faster in a set
        return (p for p in parameters if _get_name(p) in selector_set)

    # 4. unsupported selector type – return an empty iterator
    return iter(())

