def compute_sqrt(x):
    if x < 2:
        return x
    guess = x // 2
    if guess == 0:
        guess = 1
    while True:
        new_guess = (guess + x // guess) // 2
        if abs(new_guess - guess) < 2:
            return new_guess
        guess = new_guess

