class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        if not title or not author:
            print('Error: Title and author must be non-empty strings.')
            return
        self.books.append({'title': title, 'author': author})
        print(f"Book '{title}' by {author} added successfully.")

    def remove_book(self, title, author):
        if not title or not author:
            print('Error: Title and author must be non-empty strings.')
            return
        for book in self.books:
            if book['title'] == title and book['author'] == author:
                self.books.remove(book)
                print(f"Book '{title}' by {author} removed successfully.")
                return
        print(f"Error: Book '{title}' by {author} not found in the library.")

    def search_books(self, title, author):
        if (title is None or title == '') and (author is None or author == ''):
            print('Error: At least the title or author must be provided for a search.')
            return
        found_books = []
        for book in self.books:
            matches_title = title != '' and book['title'] == title
            matches_author = author != '' and book['author'] == author
            if matches_title or matches_author:
                found_books.append(book)
        if not found_books:
            print('Error: No books found with the given criteria.')
            return
        for book in found_books:
            print(f"{book['title']}|{book['author']}")

