<%
    // Initialize a sorted array (required for binary search)
    Integer[] sortedArray = {3, 7, 12, 16, 23, 28, 45};
    int target = 23;
    int low = 0;
    int high = sortedArray.length - 1;
    int resultIndex = -1;

    // Binary search algorithm
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sortedArray[mid] == target) {
            resultIndex = mid;
            break; // Found, exit loop early
        } else if (sortedArray[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    // Handle result
    if (resultIndex != -1) {
        out.println("Target found at index: " + resultIndex);
    } else {
        out.println("Target not found in the array.");
    }
%>
