import sys, math

# Count set bits in the first "size" bits of the bit-packed sieve
def _count_primes_bits(sieve: bytearray, size: int) -> int:
    full_bytes = size // 8
    bits_left  = size % 8
    cnt = 0
    for i in range(full_bytes):
        cnt += bin(sieve[i]).count('1')
    if bits_left:
        mask = (1 << bits_left) - 1
        cnt += bin(sieve[full_bytes] & mask).count('1')
    return cnt

def primes_in_interval(m: int, n: int) -> int:
    if n < 2:
        return 0
    if m < 2:
        m = 2
    size = n - m + 1                   # how many numbers we have to test

    # Bit set = prime, bit cleared = composite.
    sieve = bytearray([0xFF]) * ((size + 7) // 8)

    # Generate all primes up to sqrt(n) with a simple sieve.
    root = int(math.isqrt(n))
    small = [True] * (root + 1)
    if root >= 0:
        small[0] = small[1] = False
    for p in range(2, int(math.isqrt(root)) + 1):
        if small[p]:
            small[p * p : root + 1 : p] = [False] * len(range(p * p, root + 1, p))

    for p, is_prime in enumerate(small):
        if not is_prime:
            continue
        # First multiple of p inside [m, n]
        start = max(p * p, ((m + p - 1) // p) * p)
        for v in range(start, n + 1, p):
            idx = v - m
            sieve[idx // 8] &= ~(1 << (idx % 8))

    return _count_primes_bits(sieve, size)

