import sys
from collections import deque

def bfs_farthest(start, adj):
    far = start
    max_d = 0
    q = deque([(start, -1, 0)])
    while q:
        node, parent, dist = q.popleft()
        if dist > max_d:
            max_d = dist
            far = node
        for nxt in adj[node]:
            if nxt != parent:
                q.append((nxt, node, dist + 1))
    return far, max_d

