def kadane(arr):
    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

def maximum_sum_rectangle(matrix, R, C):
    # build row-wise prefix sums so that we can get the sum between two columns fast
    prefix = [[0]*(C+1) for _ in range(R)]
    for i in range(R):
        for j in range(C):
            prefix[i][j+1] = prefix[i][j] + matrix[i][j]

    max_sum = -10**18  # sufficiently small

    # choose left and right column borders
    for left in range(C):
        for right in range(left, C):
            temp = [0]*R  # compressed 1-D array of row sums between the two columns
            for i in range(R):
                temp[i] = prefix[i][right+1] - prefix[i][left]
            current_max = kadane(temp)
            if current_max > max_sum:
                max_sum = current_max
    return max_sum

