def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    def partition(low, high, is_first_partition):
        if is_first_partition:
            pivot_val = arr[low]
            pivot_idx = low
        else:
            mid = (low + high) // 2
            a = arr[low]
            b = arr[mid]
            c = arr[high]
            if (a <= b <= c) or (c <= b <= a):
                pivot_val = b
                pivot_idx = mid
            elif (b <= a <= c) or (c <= a <= b):
                pivot_val = a
                pivot_idx = low
            else:
                pivot_val = c
                pivot_idx = high
            arr[low], arr[pivot_idx] = arr[pivot_idx], arr[low]
        i = low + 1
        j = high
        while True:
            while i <= j and arr[i] <= pivot_val:
                i += 1
            while i <= j and arr[j] > pivot_val:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1
            else:
                break
        arr[low], arr[j] = arr[j], arr[low]
        return j
    def _quicksort(low, high, is_first_partition):
        if low < high:
            pivot_idx = partition(low, high, is_first_partition)
            _quicksort(low, pivot_idx - 1, False)
            _quicksort(pivot_idx + 1, high, False)
    _quicksort(0, len(arr)-1, True)
    return arr

def main():
