def compute_central_tendency(numbers, method):
    if method not in ['mean', 'median']:
        raise ValueError('Invalid method. Choose from "mean" or "median".')
    if not numbers:
        raise ValueError('Input list cannot be empty.')
    need_sort = False
    if method == 'median':
        need_sort = True
    if need_sort:
        numbers = sorted(numbers)
    n = len(numbers)
    if method == 'mean':
        return round(sum(numbers) / n, 3)
    if method == 'median':
        mid_point = n // 2
        if n % 2 == 0:
            return (numbers[mid_point] + numbers[mid_point - 1]) / 2
        else:
            return numbers[mid_point]

