# Decorator for role-based access control
def requires_roles(*roles):
    def wrapper(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            if 'Authorization' not in request.headers:
                # No authorization header
                raise ForbiddenError('Missing Authorization Header')
            user_id = request.headers['Authorization']
            user = User.get(user_id)
            if not user:
                # No user found
                raise ForbiddenError('User not found')
            if not set(roles).issubset(user.roles):
                # Missing role
                raise ForbiddenError('User does not have the required roles')
            return f(*args, **kwargs)
        return wrapped
    return wrapper

@app.errorhandler(ForbiddenError)
def handle_forbidden_error(error):
    response = jsonify(error.to_dict())
    response.status_code = error.status_code
    return response

@app.route('/restricted_endpoint', methods=['GET'])
@requires_roles('Admin', 'Editor')
def restricted_endpoint():
    # Exclusive content here
    return jsonify({"message": "You have accessed the restricted endpoint!"})

