      $sth->execute();

      # FETCH all in case it is a SELECT query
      while (my @row = $sth->fetchrow_array) {
        print "@row\n";
      }
    };
    if ($@) {
      print "Unable to connect to Redshift: $@\n";
    }

    # Close connection and statement handles
    $sth->finish() if defined $sth;
    $dbh->disconnect();
}

# example usage
