def is_perfect_square(num):
    if num < 0:
        return False
    if num == 0:
        return True
    i = 1
    while i * i <= num:
        if i * i == num:
            return True
        i += 1
    return False

def is_fibonacci(num):
    if num < 0:
        return False
    a, b = 0, 1
    while b < num:
        a, b = b, a + b
    return b == num

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def main():
