    if n < 0:
        print("Factorial is not defined for negative numbers")
        return
    if is_perfect_square(n):
        print("Factorial is not defined for perfect squares")
        return
    if is_fibonacci(n):
        print("Factorial is not defined for numbers in the Fibonacci sequence")
        return
    print(factorial(n))

