def find_max_length(nums):
    count_map = {0: -1}
    count = 0
    max_len = 0
    for i in range(len(nums)):
        count += 1 if nums[i] == 1 else -1
        if count in count_map:
            max_len = max(max_len, i - count_map[count])
        else:
            count_map[count] = i
    return max_len

