    if (quantity > array.length) {
        return array;
    } else {
        let result = [];
        let tempArray = [...array];

        for (let i = 0; i < quantity; i++) {
            var randomIndex = Math.floor(Math.random() * tempArray.length);
            result.push(tempArray[randomIndex]);
            tempArray.splice(randomIndex, 1);
