def classify_string(s):
    s = s.lower().replace(" ", "")
    if s == s[::-1]:
        return "Palindrome"
    from collections import Counter
    count = Counter(s)
    odd_count = sum(1 for v in count.values() if v % 2 != 0)
    if odd_count <= 1:
