class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes):
    if not nodes or nodes[0] == 'null':
        return None
    root = Node(int(nodes[0]))
    queue = [root]
    i = 1
    n = len(nodes)
    while queue and i < n:
        curr = queue.pop(0)
        if i < n and nodes[i] != 'null':
            curr.left = Node(int(nodes[i]))
            queue.append(curr.left)
        i += 1
        if i < n and nodes[i] != 'null':
            curr.right = Node(int(nodes[i]))
            queue.append(curr.right)
        i += 1
    return root

def sum_nodes(root):
    if root is None:
        return 0
    return root.val + sum_nodes(root.left) + sum_nodes(root.right)

def main():
    nodes = input().strip().split()
    root = build_tree(nodes)
    print(sum_nodes(root))

if __name__ == "__main__":
    main()

