class Point {
  constructor(x, y) {
    if (typeof x !== 'number' || typeof y !== 'number') {
      throw new Error("X and Y must be numeric values. Document requires validity!");
    }
    this.x = x;
    this.y = y;
  }

  euclideanDistance(otherPoint) {
    if (!otherPoint || typeof otherPoint.x !== 'number' || typeof otherPoint.y !== 'number') {
      throw new Error("Guest point's coordinates must be numeric to calculate Euclidean distance.");
    }
    return Math.hypot(this.x - otherPoint.x, this.y - otherPoint.y);
  }

  manhattanDistance(otherPoint) {
    if (!otherPoint || typeof otherPoint.x !== 'number' || typeof otherPoint.y !== 'number') {
      throw new Error("Hall validation failed! Guest's coordinates aren't numeric; no Manhattan luck today!");
    }
    return Math.abs(this.x - otherPoint.x) + Math.abs(this.y - otherPoint.y);
  }
}

