class SimpleBankAccount:
    """
    A simple bank account for one user, tracking balance and transactions.
    """
    def __init__(self):
        self.balance = 0.0
        self.transaction_log = []

    def deposit(self, amount):
        if amount <= 0:
            print("Invalid amount")
        else:
            self.balance += amount
            entry = f"Deposited: {amount:.1f}"
            self.transaction_log.append(entry)
            print(entry)

    def withdraw(self, amount):
        if amount <= 0:
            print("Invalid amount")
        elif amount > self.balance:
            print("Insufficient funds")
        else:
            self.balance -= amount
            entry = f"Withdrew: {amount:.1f}"
            self.transaction_log.append(entry)
            print(entry)

    def check_balance(self):
        print(f"{self.balance:.1f}")

    def print_log(self):
        for entry in self.transaction_log:
            print(entry)

