def decode_binary_string(s: str) -> str:
    result = []
    for i in range(0, len(s), 4):
        chunk = s[i:i + 4]
        low, high = 0, 16  # indices for letters a..p
        for bit in chunk:
            mid = (low + high) // 2
            if bit == '0':
                high = mid
            else:
                low = mid
        # low now points to the decoded character (0-based)
        result.append(chr(ord('a') + low))
    return ''.join(result)


